#![cfg_attr(not(test), no_std)]

extern crate alloc;

pub use rsa_upstream::*;

pub mod algorithms {
    use alloc::vec;
    use alloc::vec::Vec;

    use num_bigint::{BigUint, ModInverse, RandPrime};
    use num_traits::{One, ToPrimitive, Zero};
    use rand_core::CryptoRngCore;

    use rsa_upstream::{
        errors::{Error, Result},
        RsaPrivateKey,
    };

    const DEFAULT_EXPONENT: u64 = 65_537;

    /// Generates a multi-prime RSA keypair.
    ///
    /// This restores the public helper that existed in `rsa` 0.8. The implementation mirrors
    /// the upstream 0.9 key generation logic and constructs the final key through the public
    /// `RsaPrivateKey::from_components` API.
    pub fn generate_multi_prime_key<R: CryptoRngCore + ?Sized>(
        rng: &mut R,
        nprimes: usize,
        bit_size: usize,
    ) -> Result<RsaPrivateKey> {
        let exp = BigUint::from(DEFAULT_EXPONENT);
        generate_multi_prime_key_with_exp(rng, nprimes, bit_size, &exp)
    }

    /// Generates a multi-prime RSA keypair with a custom public exponent.
    pub fn generate_multi_prime_key_with_exp<R: CryptoRngCore + ?Sized>(
        rng: &mut R,
        nprimes: usize,
        bit_size: usize,
        exp: &BigUint,
    ) -> Result<RsaPrivateKey> {
        if nprimes < 2 {
            return Err(Error::NprimesTooSmall);
        }

        if bit_size < 64 && has_too_few_primes(nprimes, bit_size) {
            return Err(Error::TooFewPrimes);
        }

        let mut primes = vec![BigUint::zero(); nprimes];

        'next: loop {
            let mut todo = bit_size;
            if nprimes >= 7 {
                todo += (nprimes - 2) / 5;
            }

            for (i, prime) in primes.iter_mut().enumerate() {
                *prime = rng.gen_prime(todo / (nprimes - i));
                todo -= prime.bits();
            }

            for (i, prime1) in primes.iter().enumerate() {
                for prime2 in primes.iter().take(i) {
                    if prime1 == prime2 {
                        continue 'next;
                    }
                }
            }

            let n: BigUint = primes.iter().product();
            if n.bits() != bit_size {
                continue 'next;
            }

            if let Some(d) = private_exponent(&primes, exp) {
                return RsaPrivateKey::from_components(n, exp.clone(), d, primes);
            }
        }
    }

    fn private_exponent(primes: &[BigUint], exp: &BigUint) -> Option<BigUint> {
        let mut totient = BigUint::one();
        for prime in primes {
            totient *= prime - BigUint::one();
        }

        exp.mod_inverse(totient)?.to_biguint()
    }

    fn has_too_few_primes(nprimes: usize, bit_size: usize) -> bool {
        let Some(prime_limit) = (1_u64).checked_shl((bit_size / nprimes) as u32) else {
            return false;
        };
        let Some(prime_limit) = prime_limit.to_f64() else {
            return false;
        };

        let pi = prime_limit / (prime_limit.ln() - 1.0) / 4.0 / 2.0;
        pi < nprimes as f64
    }
}

