        }
    }

    fn private_exponent(primes: &[BigUint], exp: &BigUint) -> Option<BigUint> {
        let mut totient = BigUint::one();
        for prime in primes {
            totient *= prime - BigUint::one();
        }

        exp.mod_inverse(totient)?.to_biguint()
    }

    fn has_too_few_primes(nprimes: usize, bit_size: usize) -> bool {
        let Some(prime_limit) = (1_u64).checked_shl((bit_size / nprimes) as u32) else {
            return false;
        };
        let Some(prime_limit) = prime_limit.to_f64() else {
            return false;
        };

        let pi = prime_limit / (prime_limit.ln() - 1.0) / 4.0 / 2.0;
        pi < nprimes as f64
    }
}
